export function cappedRunningTotal(nums, cap) {
  const result = [];
  let total = 0;
  let capped = false;
  for (const n of nums) {
    if (!capped) {
      total += n;
      if (total >= cap) {
        total = cap;
        capped = true;
      }
    }
    result.push(total);
  }
  return result;
}
